    plans=[]
    for tree in sorted(readers,key=lambda t:t.name):
        revision=tree.get('st_port_profile_admission',0)
        if revision not in (0,1):
            raise ValueError('Unknown saved profile-admission revision: '+tree.name)
        if revision==1:
            result.append(dict(group=tree.name,changed=False));continue
        if not tree.name.startswith('Prochitecture Streets / Original Section-end port path v3 /'):
            raise ValueError('Unknown saved port-reader revision: '+tree.name)
        schema={(s.in_out,s.name):s.socket_type for s in tree.interface.items_tree if s.item_type=='SOCKET'}
        for key,kind in ((('INPUT','Ports'),'NodeSocketGeometry'),(('INPUT','Index'),'NodeSocketInt'),
                         (('OUTPUT','Geometry'),'NodeSocketGeometry'),(('OUTPUT','Valid'),'NodeSocketBool')):
            if schema.get(key)!=kind:raise ValueError('Saved port-reader interface mismatch: '+str(key))
        outputs=[n for n in tree.nodes if n.type=='GROUP_OUTPUT' and n.is_active_output]
        if len(outputs)!=1:raise ValueError('Saved port reader needs one active output')
        output=outputs[0]
        if any(len(output.inputs[k].links)!=1 for k in ('Valid','Geometry')):
            raise ValueError('Saved port reader needs linked original geometry and validity')
