    eligible=eligible*g.math('LESS_THAN',g.math('ABSOLUTE',offset[0]+offset[1]),1e-6)
    # This join has zero length at the shared knot: only the two endpoint
    # dimensions must match. A later taper on either span must not replace
    # this unchanged curb with a numerical fillet. Its corridor separately
    # verifies that both mouth cuts lie in constant-dimensional portions.
