    # contacts and the mouth. Full-path sweep consumers additionally prove
    # constant dimensions or construct the declared finite transitions.
    core = build(interpolation=interpolation, dimensions=interpolation)
    for socket in core.interface.items_tree:
        if socket.item_type == 'SOCKET' and socket.in_out == 'OUTPUT':
            g.socket(socket.name, socket.socket_type, 'OUTPUT')
    g.socket('Reverse', 'NodeSocketBool', 'OUTPUT')
