    for socket in core.interface.items_tree:
        if socket.item_type == 'SOCKET' and socket.in_out == 'OUTPUT':
            g.bind(call.outputs[socket.name], out.inputs[socket.name])
    g.bind(False, out.inputs['Reverse'])
    return g.g


